@@ -174,7 +174,9 @@ export function readPending(
 }
 export function errorMessage(error: unknown): string {
   const e = error as {
+    name?: string;
     code?: number;
+    details?: string;
     message?: string;
     shortMessage?: string;
     cause?: { code?: number };
@@ -205,6 +207,15 @@ export function errorMessage(error: unknown): string {
     return 'The model did not return a valid assessment. No review was saved.';
   if (/insufficient funds/i.test(e?.message ?? ''))
     return 'Your wallet needs Studionet GEN for network fees. No payment is sent to ReplyCheck.';
+  // Recognize only the pinned RPC client's transaction lookup error, not a
+  // missing contract/resource or a transport outage. Absence is not finality.
+  if (
+    e?.name === 'ResourceNotFoundRpcError' &&
+    e.code === -32001 &&
+    typeof e.details === 'string' &&
+    /^Transaction 0x[0-9a-f]{64} not found$/i.test(e.details)
+  )
+    return 'Transaction not found on Studionet. Check the hash in wallet Activity and try the lookup again. Keep your recovery record; do not resend.';
   // Never echo raw RPC errors: some providers include the entire submitted calldata.
   if (e?.message?.startsWith('ReplyCheck: ')) return e.message.slice(12);
   return 'The request could not be verified. Check your connection; keep any transaction hash before retrying.';
